query:
mutation networkConfigSnmpUpdateProfileList ( $accountId:ID! $networkConfigSnmpUpdateProfileListInput:NetworkConfigSnmpUpdateProfileListInput!) {
	networkConfig ( accountId:$accountId ) {
		snmp {
			updateProfileList ( input:$networkConfigSnmpUpdateProfileListInput   ) {
				snmpProfile {
					id
					name
					username
					securityLevel
					authProtocol
					privacyProtocol
					description
					audit {
						updatedTime
						updatedBy {
							id
							name
						}
					}
				}
			}
		}
	}	
}
